import Link from "next/link";
import type { ReactNode } from "react";
import type { CongressOverviewResponse, InsidersOverviewResponse, InstitutionalActivityPeriod, InstitutionsOverviewResponse, ProfileActivityByTypePeriod, ProfileActivityItem, ProfileMetric, ProfileSectorMover, ProfileSectorPeriod, ProfilesSummaryResponse } from "@/lib/api";
import { LatestProfileActivity } from "@/components/profiles/LatestProfileActivity";

const COLORS = ["#42d3a7", "#3b82f6", "#a855f7", "#f6b91a", "#fb7185", "#60a5fa", "#a3e635", "#94a3b8", "#2dd4bf", "#f97316"];
const PROFILE_COLORS: Record<string, string> = { Congress: "#42d3a7", Insider: "#3b82f6", Institution: "#a855f7", Department: "#f6b91a" };

type Row = Record<string, unknown>;

export function EnhancedProfilesOverview({ data }: { data: ProfilesSummaryResponse }) {
  const activity = (data.activity ?? []).filter((item) => item.profile && item.profile !== "Profile unavailable");
  const categories = ["Congress", "Insider", "Institution", "Department"];
  const activityMix = data.activity_mix?.length
    ? new Map(data.activity_mix.map((item) => [item.type, item.value]))
    : new Map(categories.map((type) => [type, activity.filter((item) => item.type === type).length]));
  const counts = categories.map((type) => Number(activityMix.get(type) ?? 0));
  const total = counts.reduce((sum, value) => sum + value, 0);

  return (
    <main className="relative min-w-0 space-y-3 overflow-hidden pb-3">
      <OverviewGlow />
      <header className="relative z-10 pt-2">
        <p className="text-xs font-semibold uppercase tracking-[0.28em] text-emerald-300">Profiles</p>
        <h1 className="mt-2 text-3xl font-semibold leading-tight text-white md:text-4xl">Follow the market&apos;s major players</h1>
        <p className="mt-2 max-w-4xl text-sm leading-6 text-slate-300">Track activity across Congress, corporate insiders, institutions, and government departments.</p>
      </header>
      <section className="relative z-10 grid gap-3 xl:grid-cols-4">
        {data.cards.map((card) => <OverviewCard key={card.kind} card={card} />)}
      </section>
      <section className="relative z-10 grid gap-3 xl:grid-cols-[1.25fr_.8fr_1.1fr]">
        <Panel title="Latest activity by profile type" subtitle="Monthly activity over the past two years" action="Live database data">
          <ActivityLineChart series={data.activity_by_profile_type ?? []} />
        </Panel>
        <Panel title="Where the activity is">
          <Donut values={counts} colors={categories.map((category) => PROFILE_COLORS[category])} label="Records" value={formatNumber(total)} />
          <div className="mt-4 space-y-2.5">
            {categories.map((category, index) => <LegendRow key={category} label={category} color={PROFILE_COLORS[category]} value={total ? `${((counts[index] / total) * 100).toFixed(1)}%` : "-"} />)}
          </div>
        </Panel>
        <Panel title="Top moving sectors" subtitle="Latest 365 days vs prior 365 days" action="By activity change">
          <TopMovingSectors rows={data.top_moving_sectors ?? []} />
        </Panel>
      </section>
      <section className="relative z-10 grid items-stretch gap-3 xl:grid-cols-[0.92fr_2.08fr]">
        <Panel title="Latest profile activity" action={<Link href="/feed" className="text-emerald-200 hover:text-emerald-100">View feed -&gt;</Link>}><LatestProfileActivity items={activity} /></Panel>
        <Panel title="Most active profiles">
          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
            {(data.directories?.length ? data.directories : data.cards.map((card) => ({ kind: card.kind, title: card.title, href: card.href, primary_title: card.title, primary_items: activity.filter((item) => profileKind(item.type) === card.kind).sort((left, right) => (right.value ?? 0) - (left.value ?? 0)).slice(0, 5).map((item) => ({ label: item.profile, value: item.value, value_format: "currency", href: item.profile_href })) }))).map((directory) => <DirectoryLeaders key={directory.kind} title={directory.primary_title || directory.title} href={directory.href} rows={directory.primary_items ?? []} />)}
          </div>
        </Panel>
      </section>
    </main>
  );
}

export function EnhancedCongressDashboard({ data, chamberFilter }: { data: CongressOverviewResponse; chamberFilter: ReactNode }) {
  const monthly = (data.monthly_activity ?? []).slice(-12);
  const metrics = (label: string) => data.summary.find((metric) => metric.label === label);
  const mix = [metricValue(data.summary, "Total Buy Value") ?? 0, metricValue(data.summary, "Total Sell Value") ?? 0];
  const snap = data.snapshot ?? {};
  return <main className="relative min-w-0 space-y-3 overflow-hidden pb-3"><OverviewGlow /><header className="relative z-10 flex flex-col gap-3 pt-2 md:flex-row md:items-end md:justify-between"><div><p className="text-xs font-semibold uppercase tracking-[.28em] text-emerald-300">Congress</p><h1 className="mt-2 text-3xl font-semibold text-white md:text-4xl">Congress Trading</h1><p className="mt-2 text-sm text-slate-300">Track disclosed trades, portfolio activity, and market positioning across members of Congress.</p></div>{chamberFilter}</header><section className="relative z-10 grid gap-3 xl:grid-cols-[1.7fr_.9fr]"><Panel title="Congress trading snapshot" subtitle="Monthly activity over the last 12 months"><div className="grid gap-4 md:grid-cols-[7rem_minmax(0,1fr)]"><div><p className="text-2xl font-semibold text-white">{formatNumber(Number(snap.total_trades ?? 0))}</p><p className="text-[10px] uppercase tracking-[.14em] text-slate-500">Total trades</p><MetricDelta metric={metrics("Total Trades")} /></div><CongressSnapshotTrend points={monthly.map((row) => ({ label: row.period, value: row.trades }))} /></div></Panel><div className="grid gap-3 sm:grid-cols-2"><CongressSnapshot icon="◎" label="Most active member" row={snap.top_member as Row} valueKey="trades" format="number" suffix=" trades" /><CongressSnapshot icon="◇" label="Most traded ticker" row={snap.most_traded_ticker as Row} valueKey="net_value" suffix=" Net Value" /><CongressSnapshot icon="↗" label="Top buyer" row={snap.top_buyer as Row} valueKey="value" suffix=" Net Buys" /><CongressSnapshot icon="◒" label="Most active sector" row={snap.most_active_sector as Row} valueKey="trade_percent" format="percent" suffix=" of Trades" /></div></section><section className="relative z-10 grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{data.summary.map((metric) => <CongressMetric key={metric.label} metric={metric} monthly={monthly} />)}</section><section className="relative z-10 grid gap-3 xl:grid-cols-2"><RankTable title="Top members by portfolio value" rows={data.top_members} columns={[["name", "Member", "link"], ["party", "Party"], ["chamber", "Chamber"], ["estimated_portfolio_value", "Est. portfolio value", "currency"], ["trades", "Trades", "number"], ["recent_activity", "Recent activity", "date"]]} /><RankTable title="Most traded stocks" rows={data.most_traded_stocks} columns={[["symbol", "Ticker", "link"], ["company", "Company"], ["buy_value", "Buy value", "currency"], ["sell_value", "Sell value", "currency"], ["net_value", "Net value", "currency"], ["trades", "Trades", "number"]]} /></section><section className="relative z-10 grid gap-3 xl:grid-cols-[1.05fr_.85fr_.8fr]"><VerticalSectorExposure rows={data.sector_exposure} /><SignedSectorBars rows={data.sector_activity ?? []} /><Panel title="Buy vs sell mix"><div className="flex items-center gap-4"><Donut values={mix} colors={["#42d3a7", "#fb7185"]} label="Buy" value={`${mix[0] + mix[1] ? ((mix[0] / (mix[0] + mix[1])) * 100).toFixed(0) : 0}%`} /></div></Panel></section><section className="relative z-10 grid gap-3 xl:grid-cols-[.85fr_1fr_1.15fr]"><ChamberMix rows={data.chamber_mix ?? []} /><CongressMovers rows={data.top_moving_sectors ?? []} /><NotableTrades items={data.recent_notable_trades ?? data.recent_disclosures} /></section></main>;
}

type CongressPoint = { period: string; trades: number; buy_value: number; sell_value: number; active_members: number; average_trade_size: number | null };
function MetricDelta({ metric }: { metric?: ProfileMetric }) { return typeof metric?.change_pct === "number" ? <p className={metric.change_pct >= 0 ? "mt-3 text-xs font-semibold text-emerald-300" : "mt-3 text-xs font-semibold text-rose-300"}>{metric.change_pct >= 0 ? "+" : ""}{metric.change_pct.toFixed(1)}% vs prior 12 months</p> : <p className="mt-3 text-xs text-slate-500">Latest 12 months</p>; }
function CongressSnapshotTrend({ points }: { points: Array<{ label: string; value: number }> }) { if (!points.length) return <p className="flex h-48 items-center justify-center text-sm text-slate-400">No monthly trade activity is available.</p>; const max = Math.max(...points.map((point) => point.value), 1); const axisMax = roundAxisMax(max); const ticks = [axisMax, axisMax * .75, axisMax * .5, axisMax * .25, 0]; const plotTop = 8; const plotBottom = 92; const xFor = (index: number) => (index / Math.max(points.length - 1, 1)) * 100; const yFor = (value: number) => plotBottom - (Math.max(value, 0) / axisMax) * (plotBottom - plotTop); const linePoints = points.map((point, index) => `${xFor(index)},${yFor(point.value)}`); const line = linePoints.join(" "); const area = `M${linePoints.join(" L ")} L ${xFor(points.length - 1)},${plotBottom} L ${xFor(0)},${plotBottom} Z`; return <div className="min-w-0"><div className="grid grid-cols-[3rem_minmax(0,1fr)] gap-3"><div className="flex h-48 flex-col justify-between py-1 text-right text-[10px] font-semibold tabular-nums text-slate-500">{ticks.map((tick) => <span key={tick}>{formatCompactNumber(tick)}</span>)}</div><div className="min-w-0 overflow-hidden"><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-48 w-full overflow-hidden border-b border-white/10" aria-label="Monthly Congress trade count trend">{ticks.map((tick) => <line key={tick} x1="0" x2="100" y1={yFor(tick)} y2={yFor(tick)} stroke="rgba(148,163,184,.16)" vectorEffect="non-scaling-stroke" />)}<path d={area} fill="url(#congress-trades-area)" /><polyline points={line} fill="none" stroke="#55e3b0" strokeWidth="1.8" vectorEffect="non-scaling-stroke" /><defs><linearGradient id="congress-trades-area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#42d3a7" stopOpacity=".38" /><stop offset="100%" stopColor="#42d3a7" stopOpacity=".04" /></linearGradient></defs></svg><div className="mt-2 grid gap-1 text-[10px] text-slate-500" style={{ gridTemplateColumns: `repeat(${points.length}, minmax(0, 1fr))` }}>{points.map((point) => <span key={point.label} className="truncate text-center">{point.label}</span>)}</div></div></div></div>; }
function InsiderSnapshotChart({ rows }: { rows: NonNullable<InsidersOverviewResponse["monthly_activity"]> }) {
  const points = rows.slice(-12).map((row) => ({ label: row.period, netValue: Number(row.net_value ?? 0), trades: Number(row.trades ?? 0) }));
  if (!points.length) return <p className="flex h-52 items-center justify-center text-sm text-slate-400">No monthly insider activity is available.</p>;
  const maxAbsValue = Math.max(...points.map((point) => Math.abs(point.netValue)), 1);
  const valueLimit = roundAxisMax(maxAbsValue);
  const hasNegativeValue = points.some((point) => point.netValue < 0);
  const valueMin = hasNegativeValue ? -valueLimit : 0;
  const valueMax = valueLimit;
  const valueTicks = hasNegativeValue ? [valueLimit, valueLimit * 2 / 3, valueLimit / 3, 0, -valueLimit / 3, -valueLimit * 2 / 3, -valueLimit] : [valueLimit, valueLimit * .8, valueLimit * .6, valueLimit * .4, valueLimit * .2, 0];
  const tradeLimit = roundAxisMax(Math.max(...points.map((point) => point.trades), 1));
  const tradeTicks = [tradeLimit, tradeLimit * .8, tradeLimit * .6, tradeLimit * .4, tradeLimit * .2, 0];
  const plotTop = 8;
  const plotBottom = 92;
  const xFor = (index: number) => 3 + (index / Math.max(points.length - 1, 1)) * 94;
  const yValue = (value: number) => plotBottom - ((Math.max(valueMin, Math.min(valueMax, value)) - valueMin) / Math.max(valueMax - valueMin, 1)) * (plotBottom - plotTop);
  const yTrades = (value: number) => plotBottom - (Math.max(value, 0) / tradeLimit) * (plotBottom - plotTop);
  const netPoints = points.map((point, index) => `${xFor(index)},${yValue(point.netValue)}`);
  const tradePoints = points.map((point, index) => `${xFor(index)},${yTrades(point.trades)}`);
  const zeroY = yValue(0);
  const netArea = `M${netPoints.join(" L ")} L ${xFor(points.length - 1)},${zeroY} L ${xFor(0)},${zeroY} Z`;
  const minChartWidth = Math.max(36, points.length * 3.2);
  return <div className="min-w-0">
    <div className="mb-3 flex flex-wrap justify-end gap-x-4 gap-y-1 text-[10px] text-slate-400"><span className="inline-flex items-center gap-1.5"><i className="h-2 w-2 rounded-sm bg-emerald-400" />Net Value (USD)</span><span className="inline-flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-blue-400" />Total Trades</span></div>
    <div className="grid grid-cols-[3.6rem_minmax(0,1fr)_3.2rem] gap-3">
      <div><p className="mb-1 text-[9px] font-semibold uppercase tracking-[.12em] text-slate-500">Net value</p><div className="flex h-52 flex-col justify-between text-right text-[10px] font-semibold tabular-nums text-slate-500">{valueTicks.map((tick) => <span key={tick}>{formatAxisValue(tick)}</span>)}</div></div>
      <div className="min-w-0 overflow-x-auto pb-1">
        <div style={{ minWidth: `${minChartWidth}rem` }}>
          <div className="relative h-52 overflow-hidden">
            <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 h-full w-full overflow-hidden border-b border-white/10" aria-label="Monthly insider net value and total trades">
              <defs><linearGradient id="insider-net-area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#42d3a7" stopOpacity=".42" /><stop offset="100%" stopColor="#42d3a7" stopOpacity=".05" /></linearGradient></defs>
              {valueTicks.map((tick) => <line key={tick} x1="0" x2="100" y1={yValue(tick)} y2={yValue(tick)} stroke="rgba(148,163,184,.16)" vectorEffect="non-scaling-stroke" />)}
              <line x1="0" x2="100" y1={zeroY} y2={zeroY} stroke="rgba(148,163,184,.24)" vectorEffect="non-scaling-stroke" />
              <path d={netArea} fill="url(#insider-net-area)" />
              <polyline points={netPoints.join(" ")} fill="none" stroke="#55e3b0" strokeWidth="1.8" vectorEffect="non-scaling-stroke" />
              <polyline points={tradePoints.join(" ")} fill="none" stroke="#60a5fa" strokeWidth="1.7" vectorEffect="non-scaling-stroke" />
            </svg>
            {points.map((point, index) => <span key={`${point.label}-trade-dot`} className="absolute h-2 w-2 rounded-full border border-blue-100 bg-blue-400 shadow-[0_0_8px_rgba(96,165,250,.75)]" style={{ left: `calc(${xFor(index)}% - 4px)`, top: `calc(${yTrades(point.trades)}% - 4px)` }} />)}
          </div>
          <div className="mt-2 grid gap-1 text-[10px] text-slate-500" style={{ gridTemplateColumns: `repeat(${points.length}, minmax(0, 1fr))` }}>{points.map((point) => <span key={point.label} className="truncate text-center">{point.label}</span>)}</div>
        </div>
      </div>
      <div><p className="mb-1 text-[9px] font-semibold uppercase tracking-[.12em] text-slate-500">Trades</p><div className="flex h-52 flex-col justify-between text-left text-[10px] font-semibold tabular-nums text-slate-500">{tradeTicks.map((tick) => <span key={tick}>{formatCompactNumber(tick)}</span>)}</div></div>
    </div>
  </div>;
}
function CongressTrend({ points, tone = "green" }: { points: Array<{ label: string; value: number }>; tone?: "green" | "red" | "blue" }) { const max = Math.max(...points.map((point) => point.value), 1); const plotTop = 14; const plotBottom = 96; const xFor = (index: number) => (index / Math.max(points.length - 1, 1)) * 100; const yFor = (value: number) => plotBottom - (Math.max(value, 0) / max) * (plotBottom - plotTop); const linePoints = points.map((point, index) => `${xFor(index)},${yFor(point.value)}`); const line = linePoints.join(" "); const area = `M${linePoints.join(" L ")} L ${xFor(points.length - 1)},${plotBottom} L ${xFor(0)},${plotBottom} Z`; const stroke = tone === "red" ? "#fb7185" : tone === "blue" ? "#60a5fa" : "#55e3b0"; const gradientId = `congress-metric-area-${tone}`; return <div><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-36 w-full overflow-hidden">{[25, 50, 75].map((y) => <line key={y} x1="0" x2="100" y1={y} y2={y} stroke="rgba(148,163,184,.15)" vectorEffect="non-scaling-stroke" />)}<path d={area} fill={`url(#${gradientId})`} /><polyline points={line} fill="none" stroke={stroke} strokeWidth="1.7" vectorEffect="non-scaling-stroke" /><defs><linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor={stroke} stopOpacity=".32" /><stop offset="100%" stopColor={stroke} stopOpacity=".04" /></linearGradient></defs></svg><div className="mt-2 flex justify-between text-[10px] text-slate-500"><span>{points[0]?.label}</span><span>{points.at(-1)?.label}</span></div></div>; }
function CongressSnapshot({ icon, label, row, valueKey, suffix = "", format = "currency" }: { icon: string; label: string; row?: Row; valueKey: string; suffix?: string; format?: "currency" | "number" | "percent" }) { const title = row ? stringAt(row, ["name", "symbol", "sector", "company"]) ?? "No reported record" : "No reported record"; const value = row?.[valueKey]; const display = typeof value === "number" ? `${formatCongressSnapshotValue(value, format)}${suffix}` : "-"; return <div className="rounded-lg border border-slate-700/70 bg-slate-950/65 p-4"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-lg border border-emerald-300/25 bg-emerald-300/10 text-base text-emerald-200">{icon}</span><p className="text-[10px] uppercase tracking-[.14em] text-slate-500">{label}</p></div><p className="mt-3 truncate text-sm font-semibold text-white">{title}</p><p className="mt-1 text-xs font-semibold text-emerald-300">{display}</p></div>; }
function formatCongressSnapshotValue(value: number, format: "currency" | "number" | "percent") { if (format === "number") return formatNumber(value); if (format === "percent") return `${value.toFixed(1)}%`; return formatMoney(value); }
function CongressMetric({ metric, monthly }: { metric: ProfileMetric; monthly: CongressPoint[] }) { const key = metric.label === "Total Trades" ? "trades" : metric.label === "Total Buy Value" ? "buy_value" : metric.label === "Total Sell Value" ? "sell_value" : metric.label === "Active Members" ? "active_members" : "average_trade_size"; const tone = metric.label === "Total Sell Value" ? "red" : metric.label === "Active Members" || metric.label === "Average Trade Size" ? "blue" : metric.label === "Total Trades" && typeof metric.change_pct === "number" && metric.change_pct < 0 ? "red" : "green"; return <div className="rounded-lg border border-slate-700/70 bg-slate-950/65 p-4"><p className="truncate text-[10px] uppercase tracking-[.14em] text-slate-500">{metric.label}</p><p className="mt-3 text-2xl font-semibold text-white">{formatMetric(metric)}</p><MetricDelta metric={metric} /><div className="mt-3"><CongressTrend points={monthly.map((row) => ({ label: row.period, value: Number(row[key] ?? 0) }))} tone={tone} /></div></div>; }
function RankTable({ title, rows, columns }: { title: string; rows: Row[]; columns: Array<[string, string, CellFormat?]> }) { return <Panel title={title}>{!rows.length ? <p className="py-8 text-sm text-slate-400">No reported database records are available.</p> : <div className="overflow-x-auto"><table className="min-w-[48rem] w-full text-left text-xs"><thead className="border-b border-white/10 text-[10px] uppercase tracking-[.13em] text-slate-500"><tr><th className="px-2 py-2">Rank</th>{columns.map(([, label]) => <th key={label} className="px-2 py-2">{label}</th>)}</tr></thead><tbody className="divide-y divide-white/5">{rows.slice(0, 10).map((row, index) => <tr key={index}><td className="px-2 py-2.5 text-slate-500">{index + 1}</td>{columns.map(([key, , format]) => <td key={key} className="max-w-40 truncate px-2 py-2.5 text-slate-300">{renderCell(row, key, format)}</td>)}</tr>)}</tbody></table></div>}</Panel>; }
function VerticalSectorExposure({ rows }: { rows: ProfileSectorPeriod[] }) { const periods = rows.slice(-5); const labels = sectorLabels(periods); return <Panel title="Sector exposure over time" subtitle="Reported trade value"><div className="flex h-48 items-end gap-4 border-b border-white/10 px-2">{periods.map((row) => <div key={row.period} className="flex flex-1 flex-col items-center gap-2"><div className="flex h-40 w-full max-w-10 flex-col-reverse overflow-hidden rounded-sm bg-slate-900">{orderedSegments(row, labels).map((segment) => <i key={segment.label} style={{ height: `${Math.max(segment.percent, .6)}%`, backgroundColor: colorFor(segment.label, labels) }} />)}</div><span className="text-[10px] text-slate-500">{row.period}</span></div>)}</div></Panel>; }
function SignedSectorBars({ rows }: { rows: NonNullable<CongressOverviewResponse["sector_activity"]> }) { const max = Math.max(...rows.map((row) => Math.abs(row.current_value)), 1); return <Panel title="Net activity by sector" subtitle="Green buy net, red sell net"><div className="space-y-3">{rows.slice(0, 8).map((row) => <div key={row.sector} className="grid grid-cols-[7rem_minmax(0,1fr)_4rem] gap-2 text-xs"><span className="truncate text-slate-300">{row.sector}</span><div className="relative h-2.5 rounded bg-slate-800"><i className="absolute top-0 h-full" style={{ left: row.current_value >= 0 ? "50%" : `${50 - Math.abs(row.current_value) / max * 50}%`, width: `${Math.abs(row.current_value) / max * 50}%`, backgroundColor: row.current_value >= 0 ? "#42d3a7" : "#fb7185" }} /></div><span className={row.current_value >= 0 ? "text-right text-emerald-300" : "text-right text-rose-300"}>{formatMoney(row.current_value)}</span></div>)}</div></Panel>; }
function ChamberMix({ rows }: { rows: Array<{ label: string; value: number }> }) { return <Panel title="Chamber mix" subtitle="Reported trade value">{rows.length ? <div className="flex items-center gap-3"><Donut values={rows.map((row) => row.value)} colors={["#3b82f6", "#a855f7", "#94a3b8"]} label="Value" value={formatMoney(rows.reduce((sum, row) => sum + row.value, 0))} /><div className="flex-1 space-y-2">{rows.map((row, index) => <LegendRow key={row.label} label={row.label} color={["#3b82f6", "#a855f7", "#94a3b8"][index]} value={formatMoney(row.value)} />)}</div></div> : <p className="py-8 text-sm text-slate-400">No chamber data available.</p>}</Panel>; }
function CongressMovers({ rows }: { rows: NonNullable<CongressOverviewResponse["top_moving_sectors"]> }) { const visibleRows = rows.slice(0, 6); return <Panel title="Top moving sectors" subtitle="Vs prior 12 months"><div className="overflow-hidden"><div className="grid grid-cols-[minmax(0,1fr)_4.75rem_5.75rem] gap-3 border-b border-white/10 pb-1.5 text-[9px] font-semibold uppercase tracking-[.12em] text-slate-500"><span>Sector</span><span className="text-right">Change</span><span>Trend</span></div><div className="divide-y divide-white/5">{visibleRows.map((row) => <div key={row.sector} className="grid min-h-7 grid-cols-[minmax(0,1fr)_4.75rem_5.75rem] items-center gap-3 py-1.5 text-[11px]"><span className="truncate text-slate-300">{row.sector}</span><span className={typeof row.change_pct === "number" && row.change_pct >= 0 ? "text-right font-semibold tabular-nums text-emerald-300" : "text-right font-semibold tabular-nums text-rose-300"}>{typeof row.change_pct === "number" ? `${row.change_pct >= 0 ? "+" : ""}${row.change_pct.toFixed(1)}%` : "-"}</span><CompactSparkline points={row.trend.slice(-12)} positive={typeof row.change_pct !== "number" || row.change_pct >= 0} /></div>)}</div></div></Panel>; }
function CompactSparkline({ points, positive = true }: { points: Array<{ label: string; value: number }>; positive?: boolean }) { if (!points.length) return <span className="block h-5 w-full overflow-hidden rounded-sm bg-slate-950/50" />; const values = points.map((point) => point.value); const min = Math.min(...values); const max = Math.max(...values); const spread = Math.max(max - min, 1); const line = points.map((point, index) => { const x = (index / Math.max(points.length - 1, 1)) * 100; const y = max === min ? 10 : 18 - ((point.value - min) / spread) * 14; return `${x},${y}`; }).join(" "); return <span className="block h-5 w-full overflow-hidden rounded-sm bg-slate-950/40"><svg viewBox="0 0 100 20" preserveAspectRatio="none" className="h-full w-full overflow-hidden"><polyline points={line} fill="none" stroke={positive ? "#55e3b0" : "#fb7185"} strokeWidth="1.6" vectorEffect="non-scaling-stroke" /></svg></span>; }
function NotableTrades({ items }: { items: ProfileActivityItem[] }) { return <Panel title="Recent notable trades">{items.length ? <div className="overflow-x-auto"><table className="min-w-[31rem] w-full text-left text-xs"><thead className="border-b border-white/10 text-[10px] uppercase tracking-[.13em] text-slate-500"><tr>{["Member", "Ticker", "Action", "Value", "Date"].map((label) => <th key={label} className="px-2 py-2">{label}</th>)}</tr></thead><tbody>{items.slice(0, 7).map((item) => { const action = congressTradeAction(item.activity); return <tr key={String(item.id)} className="border-b border-white/5"><td className="px-2 py-2.5 font-semibold text-emerald-200">{item.profile}</td><td className="px-2 py-2.5 text-slate-300">{item.symbol ?? "-"}</td><td className={`px-2 py-2.5 font-semibold ${action.className}`}>{action.label}</td><td className="px-2 py-2.5 text-white">{formatMoney(item.value)}</td><td className="px-2 py-2.5 text-slate-400">{item.time ? formatDate(item.time) : "-"}</td></tr>; })}</tbody></table></div> : <p className="py-8 text-sm text-slate-400">No recent trades available.</p>}</Panel>; }
function congressTradeAction(value: string | null | undefined) { const normalized = String(value ?? "").trim().toLowerCase(); if (normalized.includes("purchase") || normalized === "buy") return { label: "Buy", className: "text-emerald-300" }; if (normalized.includes("sale") || normalized === "sell") return { label: "Sell", className: "text-rose-300" }; return { label: value || "-", className: "text-slate-300" }; }

export function EnhancedInsiderDashboard({ data, periodFilter }: { data: InsidersOverviewResponse; periodFilter: ReactNode }) {
  return <ProfileDashboard
    flavor="insiders"
    eyebrow="INSIDERS"
    title="Corporate Insider Activity"
    subtitle="Track purchases and sales from executives, directors, and major shareholders."
    filter={periodFilter}
    comparison={`previous ${data.period_days} days`}
    snapshotTitle="Insider trading snapshot"
    snapshotSeries={periodTotals(data.sector_activity)}
    snapshotLabel="Net insider activity (USD)"
    snapshotContent={<InsiderSnapshotChart rows={data.monthly_activity ?? []} />}
    metrics={data.summary}
    primary={{ title: "Top insiders by net buying", rows: data.top_insiders, columns: [["name", "Insider", "link"], ["company", "Company"], ["role", "Role"], ["net_buy_value", "Net buy value", "currency"], ["trades", "Trades", "number"]] }}
    secondary={{ title: "Most traded stocks", rows: data.most_traded_stocks, columns: [["symbol", "Ticker", "link"], ["company", "Company"], ["buy_value", "Buy value", "currency"], ["sell_value", "Sell value", "currency"], ["net_value", "Net value", "currency"]] }}
    sectorRows={data.sector_activity}
    sectorTitle="Insider activity by sector"
    left={{ title: "Recent open-market purchases", rows: data.recent_purchases as Row[], columns: [["profile", "Insider", "link"], ["symbol", "Ticker", "link"], ["activity", "Action"], ["value", "Value", "currency"], ["time", "Date", "date"]] }}
    right={{ title: "Cluster buying", rows: data.cluster_buying, columns: [["symbol", "Ticker", "link"], ["company", "Company"], ["unique_insiders", "Insiders", "number"], ["buy_value", "Buy value", "currency"]] }}
    recent={data.largest_buys}
  />;
}

export function EnhancedInstitutionDashboard({ data, period }: { data: InstitutionsOverviewResponse; period: string }) {
  if (data.locked) {
    return <ProfileDashboard flavor="institutions" eyebrow="INSTITUTIONS" title="Institutional Holdings" subtitle="Track institutional portfolios, quarterly position changes, accumulation, and sector exposure." filter={<PeriodBadge label={period} />} comparison="previous comparable quarter" snapshotTitle="Institutional holdings snapshot" snapshotSeries={[]} snapshotLabel="Institutional detail is available with Pro." metrics={data.summary} primary={{ title: "Top institutions", rows: [], columns: [] }} secondary={{ title: "Top increased positions", rows: [], columns: [] }} sectorRows={[]} sectorTitle="Sector exposure over time" left={{ title: "Most widely held stocks", rows: [], columns: [] }} right={{ title: "Recent notable filings", rows: [], columns: [] }} recent={[]} lockedMessage={data.message} />;
  }
  return <ProfileDashboard
    flavor="institutions"
    eyebrow="INSTITUTIONS"
    title="Institutional Holdings"
    subtitle="Track institutional portfolios, quarterly position changes, accumulation, and sector exposure."
    filter={<PeriodBadge label={period} />}
    comparison="previous comparable quarter"
    snapshotTitle="Institutional holdings snapshot"
    snapshotSeries={periodTotals(data.sector_exposure)}
    snapshotLabel="Aggregate reported portfolio value by filing quarter"
    metrics={data.summary}
    primary={{ title: "Top institutions by portfolio value", rows: data.top_institutions, columns: [["name", "Institution", "link"], ["portfolio_value", "Portfolio value", "currency"], ["previous_value", "Previous quarter", "currency"], ["qoq_change", "QoQ change", "percent"], ["positions", "Positions", "number"]] }}
    secondary={{ title: "Top increased positions", rows: data.position_changes, columns: [["symbol", "Ticker", "link"], ["company", "Company"], ["current_value", "Current value", "currency"], ["previous_value", "Previous value", "currency"], ["increase_value", "Increase", "currency"]] }}
    sectorRows={data.sector_exposure}
    institutionalActivity={data.institutional_activity_over_time ?? []}
    sectorTitle="Sector exposure over time"
    left={{ title: "Most widely held stocks", rows: data.most_widely_held, columns: [["symbol", "Ticker", "link"], ["company", "Company"], ["value", "Total value", "currency"], ["holders", "Institutions", "number"]] }}
    right={{ title: "Recent notable filings", rows: data.recent_filings, columns: [["name", "Institution", "link"], ["symbol", "Ticker", "link"], ["action", "Action"], ["value", "Value", "currency"], ["filing_date", "Date", "date"]] }}
    recent={data.largest_new_positions as unknown as ProfileActivityItem[]}
  />;
}

type TableSpec = { title: string; rows: Row[]; columns: Array<[string, string, CellFormat?]> };
type CellFormat = "currency" | "number" | "date" | "percent" | "link";

type DashboardFlavor = "congress" | "insiders" | "institutions";

function ProfileDashboard({ flavor, eyebrow, title, subtitle, filter, comparison, snapshotTitle, snapshotSeries, snapshotLabel, snapshotContent, metrics, primary, secondary, sectorRows, sectorTitle, left, right, recent, note, lockedMessage, institutionalActivity = [] }: { flavor: DashboardFlavor; eyebrow: string; title: string; subtitle: string; filter: ReactNode; comparison: string; snapshotTitle: string; snapshotSeries: Array<{ label: string; value: number }>; snapshotLabel: string; snapshotContent?: ReactNode; metrics: ProfileMetric[]; primary: TableSpec; secondary: TableSpec; sectorRows: ProfileSectorPeriod[]; sectorTitle: string; left: TableSpec; right: TableSpec; recent: ProfileActivityItem[]; note?: string; lockedMessage?: string | null; institutionalActivity?: InstitutionalActivityPeriod[] }) {
  const snapshotStats = [primary.rows[0], secondary.rows[0], left.rows[0], right.rows[0]];
  return <main className="relative min-w-0 space-y-3 overflow-hidden pb-3">
    <OverviewGlow />
    <header className="relative z-10 flex flex-col gap-3 pt-2 md:flex-row md:items-end md:justify-between">
      <div><p className="text-xs font-semibold uppercase tracking-[0.28em] text-emerald-300">{eyebrow}</p><h1 className="mt-2 text-3xl font-semibold leading-tight text-white md:text-4xl">{title}</h1><p className="mt-2 text-sm leading-6 text-slate-300">{subtitle}</p></div>
      {filter}
    </header>
      <section className="relative z-10 grid gap-3 xl:grid-cols-[1.68fr_.9fr]">
        <Panel title={snapshotTitle} subtitle={snapshotLabel} action="Live data">{snapshotContent ?? <TrendChart series={snapshotSeries} />}</Panel>
      <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-2">
        {snapshotStats.map((row, index) => <SnapshotCard key={index} row={row} label={snapshotLabels(flavor)[index]} />)}
      </div>
    </section>
    <MetricCards metrics={metrics} comparison={comparison} />
    {lockedMessage ? <Panel title="Institutional detail"><p className="text-sm leading-6 text-slate-300">{lockedMessage}</p><Link href="/pricing" className="mt-4 inline-flex text-sm font-semibold text-emerald-200 hover:text-emerald-100">View Pro access -&gt;</Link></Panel> : <>
      <section className="grid gap-3 xl:grid-cols-2"><DataTable {...primary} /><DataTable {...secondary} /></section>
      <section className="grid gap-3 xl:grid-cols-[1.05fr_.85fr_.8fr]">
        <SectorPanel title={sectorTitle} rows={sectorRows} note={note} />
        {flavor === "institutions" ? <Panel title="Net position change by sector" action="QoQ change"><NetPositionChangeBySector rows={sectorRows} /></Panel> : <Panel title="Net activity by sector"><SectorMomentum rows={sectorRows} /></Panel>}
        <Panel title={flavor === "institutions" ? "Increases vs decreases mix" : "Buy vs sell mix"}><ActivityMix flavor={flavor} metrics={metrics} /></Panel>
      </section>
      <section className="grid gap-3 xl:grid-cols-[.9fr_1fr_1.1fr]"><DataTable {...left} /><DataTable {...right} /><Panel title="Top moving sectors"><SectorMovers rows={sectorRows} /></Panel></section>
      {flavor === "institutions" ? <Panel title="Activity over time (quarterly)" action="8 quarters"><InstitutionalActivityOverTime rows={institutionalActivity} /></Panel> : <section className="grid gap-3 xl:grid-cols-[1.15fr_.85fr]"><Panel title="Activity over time" subtitle="Reported value by period"><ActivityColumns series={snapshotSeries} /></Panel><Panel title="Recent notable activity"><CompactActivity items={recent} /></Panel></section>}
    </>}
  </main>;
}

function OverviewCard({ card }: { card: ProfilesSummaryResponse["cards"][number] }) {
  const chartMetric = overviewChartMetric(card);
  const chartValues = overviewChartValues(chartMetric, card.kind);

  return <Link href={card.href} prefetch={false} className="group min-w-0 overflow-hidden rounded-lg border border-slate-700/70 bg-slate-950/65 p-4 transition hover:border-emerald-300/45 hover:bg-slate-900/80">
    <div className="flex items-start justify-between gap-3">
      <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg border border-emerald-300/30 bg-emerald-300/10 text-lg text-emerald-200">{profileIcon(card.kind)}</span>
      <div className="min-w-[7rem] flex-1 sm:max-w-[9rem]">
        <OverviewMiniChart id={`profile-card-${card.kind}`} values={chartValues} />
      </div>
    </div>
    <h2 className="mt-3 text-base font-semibold text-white">{card.title}</h2><p className="mt-1 min-h-10 text-xs leading-5 text-slate-300">{card.description}</p>
    <div className="mt-3 grid grid-cols-2 gap-2">{card.metrics.slice(0, 2).map((metric) => <div key={metric.label} className="rounded-md border border-slate-700/80 bg-slate-950/80 p-3"><p className="text-lg font-semibold tabular-nums text-white">{formatMetric(metric)}</p><p className="mt-1 truncate text-[10px] font-semibold uppercase tracking-[.12em] text-slate-500">{metric.label}</p><p className={`mt-1 truncate text-[10px] font-semibold tabular-nums ${typeof metric.change_pct === "number" ? metric.change_pct >= 0 ? "text-emerald-300" : "text-rose-300" : "text-slate-500"}`}>{typeof metric.change_pct === "number" ? `${metric.change_pct >= 0 ? "+" : ""}${metric.change_pct.toFixed(1)}%` : "No prior comparable"}</p></div>)}</div>
    <p className="mt-2 truncate text-[10px] text-slate-500">{card.comparison_label ?? "Latest available period"}</p>
    <span className="mt-3 inline-flex text-sm font-semibold text-emerald-200">View {card.title} -&gt;</span>
  </Link>;
}

function OverviewMiniChart({ id, values }: { id: string; values: number[] }) {
  const max = Math.max(...values, 1);
  const min = Math.min(...values, max);
  const range = Math.max(max - min, max * 0.18, 1);
  const plotTop = 6;
  const plotBottom = 54;
  const barWidth = 120 / Math.max(values.length * 1.55, 1);
  const points = values.map((value, index) => {
    const x = (index / Math.max(values.length - 1, 1)) * 118 + 1;
    const y = plotBottom - ((value - min) / range) * (plotBottom - plotTop);
    return `${x},${Math.max(plotTop, Math.min(plotBottom, y))}`;
  });
  const area = `M 1 ${plotBottom} L ${points.join(" L ")} L 119 ${plotBottom} Z`;

  return <svg viewBox="0 0 120 60" preserveAspectRatio="none" className="h-16 w-full overflow-visible" aria-hidden="true">
    <defs><linearGradient id={`${id}-area`} x1="0" x2="0" y1="0" y2="1"><stop stopColor="#42d3a7" stopOpacity=".34" /><stop offset="1" stopColor="#42d3a7" stopOpacity="0" /></linearGradient></defs>
    <path d={area} fill={`url(#${id}-area)`} />
    {values.map((value, index) => {
      const normalized = (value - min) / range;
      const height = Math.max(5, normalized * 38 + 7);
      const x = 2 + index * (116 / Math.max(values.length - 1, 1)) - barWidth / 2;
      return <rect key={`${value}-${index}`} x={x} y={plotBottom - height} width={barWidth} height={height} rx="1" fill="#42d3a7" opacity=".58" />;
    })}
    <polyline points={points.join(" ")} fill="none" stroke="#6ff0bf" strokeWidth="1.6" vectorEffect="non-scaling-stroke" />
  </svg>;
}

function Panel({ title, subtitle, action, children }: { title: string; subtitle?: string; action?: ReactNode; children: ReactNode }) {
  return <section className="min-w-0 rounded-lg border border-slate-700/70 bg-slate-950/65 p-4 shadow-[0_18px_50px_rgba(0,0,0,.18)]"><div className="flex flex-wrap items-start justify-between gap-2"><div><h2 className="text-sm font-semibold uppercase tracking-[.15em] text-white">{title}</h2>{subtitle ? <p className="mt-1 text-xs text-slate-400">{subtitle}</p> : null}</div>{action ? <span className="text-[10px] font-semibold uppercase tracking-[.12em] text-slate-400">{action}</span> : null}</div><div className="mt-4">{children}</div></section>;
}

function MetricCards({ metrics, comparison }: { metrics: ProfileMetric[]; comparison: string }) { return <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{metrics.map((metric) => <div key={metric.label} className="min-w-0 rounded-lg border border-slate-700/70 bg-slate-950/65 p-4"><p className="truncate text-[10px] font-semibold uppercase tracking-[.16em] text-slate-500">{metric.label}</p><p className="mt-3 truncate text-2xl font-semibold tabular-nums text-white">{formatMetric(metric)}</p><p className={`mt-2 text-xs font-semibold tabular-nums ${typeof metric.change_pct === "number" ? metric.change_pct >= 0 ? "text-emerald-300" : "text-rose-300" : "text-slate-500"}`}>{typeof metric.change_pct === "number" ? `${metric.change_pct >= 0 ? "+" : ""}${metric.change_pct.toFixed(1)}% vs ${comparison}` : "Latest available period"}</p></div>)}</section>; }

function DataTable({ title, rows, columns }: TableSpec) { return <Panel title={title}>{!rows.length ? <p className="py-8 text-sm text-slate-400">No database records are available for this selection.</p> : <div className="overflow-x-auto"><table className="min-w-[38rem] w-full text-left text-xs"><thead className="border-b border-white/10 text-[10px] uppercase tracking-[.13em] text-slate-500"><tr>{columns.map(([, label]) => <th key={label} className="px-2 py-2.5 font-semibold">{label}</th>)}</tr></thead><tbody className="divide-y divide-white/5">{rows.slice(0, 10).map((row, index) => <tr key={index}>{columns.map(([key, , format]) => <td key={key} className="max-w-44 truncate px-2 py-2.5 text-slate-300">{renderCell(row, key, format)}</td>)}</tr>)}</tbody></table></div>}</Panel>; }

function SectorPanel({ title, rows, note }: { title: string; rows: ProfileSectorPeriod[]; note?: string }) { const labels = sectorLabels(rows); return <Panel title={title} subtitle="Latest-quarter ordering is kept across every period."><div className="space-y-3">{rows.map((row) => <div key={row.period} className="grid grid-cols-[3.5rem_minmax(0,1fr)] items-center gap-2"><span className="text-[10px] font-semibold text-slate-400">{row.period}</span><div className="flex h-8 overflow-hidden rounded-sm bg-slate-900">{orderedSegments(row, labels).map((segment) => <span key={segment.label} title={`${segment.label}: ${segment.percent.toFixed(1)}%`} style={{ width: `${Math.max(segment.percent, .8)}%`, backgroundColor: colorFor(segment.label, labels) }} />)}</div></div>)}</div><div className="mt-4 flex flex-wrap gap-x-3 gap-y-2">{labels.map((label) => <span key={label} className="inline-flex items-center gap-1.5 text-[10px] text-slate-400"><i className="h-2 w-2 rounded-full" style={{ backgroundColor: colorFor(label, labels) }} />{label}</span>)}</div>{note ? <p className="mt-4 text-xs leading-5 text-slate-500">{note}</p> : null}</Panel>; }

function SectorBreakdown({ rows }: { rows: ProfileSectorPeriod[] }) { const labels = sectorLabels(rows); const latest = rows[rows.length - 1]; return latest ? <div className="space-y-3">{orderedSegments(latest, labels).slice(0, 8).map((segment) => <div key={segment.label} className="grid grid-cols-[minmax(0,1fr)_3rem] gap-3 text-xs"><span className="flex min-w-0 items-center gap-2 truncate text-slate-300"><i className="h-2 w-2 shrink-0 rounded-full" style={{ backgroundColor: colorFor(segment.label, labels) }} />{segment.label}</span><span className="text-right font-semibold text-white">{segment.percent.toFixed(1)}%</span></div>)}</div> : <p className="py-8 text-sm text-slate-400">No sector records are available.</p>; }

function TrendChart({ series }: { series: Array<{ label: string; value: number }> }) { if (!series.length) return <p className="flex h-40 items-center justify-center text-sm text-slate-400">No time-series records are available.</p>; const max = Math.max(...series.map((point) => point.value), 1); const ticks = [max, max / 2, 0]; const plotTop = 8; const plotBottom = 92; const points = series.map((point, index) => { const x = (index / Math.max(series.length - 1, 1)) * 100; const y = plotBottom - (Math.max(point.value, 0) / max) * (plotBottom - plotTop); return `${x},${y}`; }).join(" "); return <div className="min-w-0"><div className="grid grid-cols-[3.8rem_minmax(0,1fr)] gap-3"><div className="flex h-40 flex-col justify-between py-1 text-right text-[10px] font-semibold tabular-nums text-slate-500">{ticks.map((tick) => <span key={tick}>{formatAxisValue(tick)}</span>)}</div><div className="min-w-0"><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-40 w-full overflow-hidden"><defs><linearGradient id="profile-trend" x1="0" x2="0" y1="0" y2="1"><stop stopColor="#42d3a7" stopOpacity=".35" /><stop offset="1" stopColor="#42d3a7" stopOpacity="0" /></linearGradient></defs>{[plotTop, (plotTop + plotBottom) / 2, plotBottom].map((y) => <line key={y} x1="0" x2="100" y1={y} y2={y} stroke="rgba(148,163,184,.16)" vectorEffect="non-scaling-stroke" />)}<polyline points={`0,${plotBottom} ${points} 100,${plotBottom}`} fill="url(#profile-trend)" stroke="none" /><polyline points={points} fill="none" stroke="#55e3b0" strokeWidth="1.7" vectorEffect="non-scaling-stroke" /></svg><div className="mt-2 grid gap-1 text-[10px] text-slate-500" style={{ gridTemplateColumns: `repeat(${series.length}, minmax(0, 1fr))` }}>{series.map((point) => <span key={point.label} className="truncate text-center">{point.label}</span>)}</div></div></div></div>; }

function ActivityLineChart({ series }: { series: ProfileActivityByTypePeriod[] }) {
  if (!series.length) return <p className="flex h-44 items-center justify-center text-sm text-slate-400">No historical database activity is available.</p>;

  const categories = ["Congress", "Insider", "Institution", "Department"] as const;
  const max = Math.max(...series.flatMap((point) => categories.map((category) => point[category])), 1);
  const axisMax = roundAxisMax(max);
  const yTicks = [axisMax, axisMax * 2 / 3, axisMax / 3, 0];
  const plotTop = 8;
  const plotBottom = 92;
  const minChartWidth = Math.max(38, series.length * 3.25);
  const yFor = (value: number) => plotBottom - (Math.max(value, 0) / axisMax) * (plotBottom - plotTop);
  const line = (category: typeof categories[number]) => series.map((point, index) => `${(index / Math.max(series.length - 1, 1)) * 100},${yFor(point[category])}`).join(" ");

  return <div>
    <div className="flex flex-wrap gap-x-3 gap-y-1 text-[10px] text-slate-400">{categories.map((category) => <span key={category} className="inline-flex items-center gap-1.5"><i className="h-2 w-2 rounded-full" style={{ backgroundColor: PROFILE_COLORS[category] }} />{category}</span>)}</div>
    <div className="mt-3 grid grid-cols-[3.2rem_minmax(0,1fr)] gap-3">
      <div className="flex h-40 flex-col justify-between py-1 text-right text-[10px] font-semibold tabular-nums text-slate-500">{yTicks.map((tick) => <span key={tick}>{formatCompactNumber(tick)}</span>)}</div>
      <div className="min-w-0 overflow-x-auto pb-1">
        <div style={{ minWidth: `${minChartWidth}rem` }}>
          <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-40 w-full overflow-visible border-b border-white/10">
            {yTicks.map((tick) => <line key={tick} x1="0" x2="100" y1={yFor(tick)} y2={yFor(tick)} stroke="rgba(148,163,184,.16)" vectorEffect="non-scaling-stroke" />)}
            {categories.map((category) => <polyline key={category} points={line(category)} fill="none" stroke={PROFILE_COLORS[category]} strokeWidth="1.5" vectorEffect="non-scaling-stroke" />)}
          </svg>
          <div className="mt-2 grid gap-1 text-[10px] text-slate-500" style={{ gridTemplateColumns: `repeat(${series.length}, minmax(0, 1fr))` }}>{series.map((point) => <span key={point.period} className="truncate text-center">{point.period}</span>)}</div>
        </div>
      </div>
    </div>
  </div>;
}

function TopMovingSectors({ rows }: { rows: ProfileSectorMover[] }) { if (!rows.length) return <p className="flex h-44 items-center justify-center text-sm text-slate-400">No sector-mapped activity is available.</p>; const max = Math.max(...rows.map((row) => row.current_value), 1); return <div><div className="space-y-2.5">{rows.map((row) => <div key={row.sector} className="grid grid-cols-[minmax(0,7.5rem)_minmax(0,1fr)_3.5rem] items-center gap-2 text-xs"><span className="truncate text-slate-300">{row.sector}</span><div className="flex h-2.5 overflow-hidden rounded-sm bg-slate-800" title={`${row.current_value.toLocaleString()} recent activities vs ${row.previous_value.toLocaleString()} prior activities`}>{row.segments.map((segment) => segment.value ? <span key={segment.type} style={{ width: `${(segment.value / max) * 100}%`, backgroundColor: PROFILE_COLORS[segment.type] }} /> : null)}</div><span className={`text-right font-semibold tabular-nums ${row.change >= 0 ? "text-emerald-300" : "text-rose-300"}`}>{row.change >= 0 ? "+" : ""}{formatNumber(row.change)}</span></div>)}</div><div className="mt-4 flex flex-wrap gap-x-3 gap-y-1 text-[10px] text-slate-400">{["Congress", "Insider", "Institution", "Department"].map((category) => <span key={category} className="inline-flex items-center gap-1.5"><i className="h-2 w-2 rounded-full" style={{ backgroundColor: PROFILE_COLORS[category] }} />{category}</span>)}</div></div>; }

function Donut({ values, colors, label, value }: { values: number[]; colors: string[]; label: string; value: string }) { const total = values.reduce((sum, item) => sum + item, 0); let offset = 0; return <div className="relative mx-auto h-36 w-36"><svg viewBox="0 0 42 42" className="h-full w-full -rotate-90">{values.map((item, index) => { const dash = total ? (item / total) * 100 : 0; const segment = <circle key={index} cx="21" cy="21" r="15.915" fill="none" stroke={colors[index]} strokeWidth="7" strokeDasharray={`${dash} ${100 - dash}`} strokeDashoffset={-offset} />; offset += dash; return segment; })}</svg><div className="absolute inset-0 flex flex-col items-center justify-center"><b className="text-lg tabular-nums text-white">{value}</b><span className="text-[9px] uppercase tracking-[.14em] text-slate-500">{label}</span></div></div>; }

function SnapshotCard({ row, label }: { row: Row | undefined; label: string }) { if (!row) return <div className="rounded-lg border border-slate-700/70 bg-slate-950/65 p-4"><p className="text-[10px] uppercase tracking-[.14em] text-slate-500">{label}</p><p className="mt-3 text-sm text-slate-400">No record available</p></div>; const title = stringAt(row, ["name", "symbol", "profile", "company"]) ?? "Live result"; const detail = valueAt(row, ["net_value", "net_buy_value", "increase_value", "portfolio_value", "value", "buy_value", "trades"]); const recentDate = stringAt(row, ["filing_date", "last_transaction", "last_activity", "recent_activity"]); return <div className="rounded-lg border border-slate-700/70 bg-slate-950/65 p-4"><p className="text-[10px] uppercase tracking-[.14em] text-slate-500">{label}</p><p className="mt-2 truncate text-sm font-semibold text-white">{title}</p><p className="mt-2 text-sm font-semibold tabular-nums text-emerald-300">{detail !== null ? formatUnknown(detail) : recentDate ? formatDate(recentDate) : "-"}</p></div>; }

function CompactActivity({ items }: { items: ProfileActivityItem[] }) { return !items.length ? <p className="py-8 text-sm text-slate-400">No recent database activity is available.</p> : <div className="space-y-0.5">{items.slice(0, 6).map((item) => <div key={String(item.id)} className="grid grid-cols-[minmax(0,1fr)_4.5rem_5rem] items-center gap-3 border-b border-white/5 py-2 text-xs"><span className="truncate font-semibold text-emerald-200">{item.profile}</span><span className="truncate text-slate-400">{item.symbol ?? item.activity ?? "-"}</span><span className="text-right font-semibold tabular-nums text-white">{formatUnknown(item.value)}</span></div>)}</div>; }

function DirectoryLeaders({ title, href, rows }: { title: string; href: string; rows: Array<{ label: string; value?: number | null; value_format?: string; href?: string | null }> }) { const visibleRows = rows.slice(0, 5); const max = Math.max(...visibleRows.map((row) => Math.abs(row.value ?? 0)), 1); return <div className="min-w-0 border-l border-white/10 pl-3 first:border-l-0 first:pl-0"><h3 className="truncate text-[11px] font-semibold text-white">{title}</h3><div className="mt-2 space-y-1.5">{visibleRows.map((row, index) => { const label = row.href ? <Link href={row.href} prefetch={false} className="truncate text-slate-300 hover:text-emerald-100">{row.label}</Link> : <span className="truncate text-slate-300">{row.label}</span>; const width = Math.max(3, (Math.abs(row.value ?? 0) / max) * 100); return <div key={`${row.label}-${index}`} className="grid grid-cols-[0.9rem_minmax(0,1fr)_minmax(2rem,3.2rem)_4.2rem] items-center gap-1.5 text-[11px]"><span className="text-slate-500">{index + 1}</span>{label}<span className="h-px overflow-hidden rounded bg-slate-800"><i className="block h-full rounded bg-emerald-300" style={{ width: `${width}%` }} /></span><span className="text-right font-semibold tabular-nums text-white">{row.value_format === "currency" ? formatMoney(row.value) : formatNumber(row.value)}</span></div>; })}</div><Link href={href} className="mt-3 inline-flex text-[11px] font-semibold text-emerald-200">View {title} -&gt;</Link></div>; }

function PeriodBadge({ label }: { label: string }) { return <span className="rounded-full border border-white/10 bg-slate-950/60 px-4 py-2 text-xs font-semibold text-slate-200">{label}</span>; }
function ActivityMix({ flavor, metrics }: { flavor: DashboardFlavor; metrics: ProfileMetric[] }) { const labels = flavor === "institutions" ? ["Increases", "Decreases"] : ["Buy value", "Sell value"]; const values = flavor === "institutions" ? [metricValue(metrics, "Total Position Increases"), metricValue(metrics, "Total Position Decreases")] : [metricValue(metrics, "Total Buy Value") ?? metricValue(metrics, "Buy Value"), metricValue(metrics, "Total Sell Value") ?? metricValue(metrics, "Sell Value")]; const total = values.reduce<number>((sum, value) => sum + Math.max(value ?? 0, 0), 0); if (!total) return <p className="py-8 text-sm text-slate-400">No matching database activity is available.</p>; const primaryPct = ((values[0] ?? 0) / total) * 100; return <div className="flex items-center gap-4"><Donut values={values.map((value) => Math.max(value ?? 0, 0))} colors={["#42d3a7", "#fb7185"]} label={labels[0]} value={`${primaryPct.toFixed(1)}%`} /><div className="min-w-0 flex-1 space-y-3">{labels.map((label, index) => <LegendRow key={label} label={label} color={index ? "#fb7185" : "#42d3a7"} value={flavor === "institutions" ? formatNumber(values[index]) : formatMoney(values[index])} />)}<p className="border-t border-white/10 pt-3 text-xs text-slate-400">Total {flavor === "institutions" ? "position changes" : "reported value"}: <span className="font-semibold text-white">{flavor === "institutions" ? formatNumber(total) : formatMoney(total)}</span></p></div></div>; }
function NetPositionChangeBySector({ rows }: { rows: ProfileSectorPeriod[] }) { const movements = sectorMovements(rows).slice(0, 8); if (!movements.length) return <p className="py-8 text-sm text-slate-400">No comparable sector periods are available.</p>; const max = Math.max(...movements.map((item) => Math.abs(item.value)), 1); return <div><div className="space-y-2.5">{movements.map((item) => { const width = Math.max(2, (Math.abs(item.value) / max) * 50); return <div key={item.label} className="grid grid-cols-[minmax(0,7.5rem)_minmax(0,1fr)_4.75rem] items-center gap-2 text-xs"><span className="truncate text-slate-300">{item.label}</span><div className="relative h-3 overflow-hidden rounded-sm bg-slate-900"><span className="absolute inset-y-0 left-1/2 w-px bg-slate-500/35" />{item.value >= 0 ? <span className="absolute left-1/2 top-0 h-full rounded-sm bg-emerald-400/80" style={{ width: `${width}%` }} /> : <span className="absolute top-0 h-full rounded-sm bg-rose-400/80" style={{ left: `${50 - width}%`, width: `${width}%` }} />}</div><span className={item.value >= 0 ? "text-right font-semibold tabular-nums text-emerald-300" : "text-right font-semibold tabular-nums text-rose-300"}>{formatMoney(item.value)}</span></div>; })}</div><div className="mt-3 grid grid-cols-[7.5rem_minmax(0,1fr)_4.75rem] gap-2 text-[10px] text-slate-500"><span /><div className="flex justify-between"><span>{formatMoney(-max)}</span><span>0</span><span>{formatMoney(max)}</span></div><span /></div></div>; }
function InstitutionalActivityOverTime({ rows }: { rows: InstitutionalActivityPeriod[] }) { const periods = rows.slice(-8); if (!periods.length) return <p className="flex h-48 items-center justify-center text-sm text-slate-400">No quarterly institutional activity is available.</p>; const valueLimit = 2_000_000_000_000; const valueTicks = [valueLimit, valueLimit / 2, 0, -valueLimit / 2, -valueLimit]; const totalMax = Math.max(...periods.map((row) => row.total_positions), 1); const totalTop = roundAxisMax(totalMax); const xFor = (index: number) => 8 + (index / Math.max(periods.length - 1, 1)) * 84; const yValue = (value: number) => 50 - (Math.max(-valueLimit, Math.min(valueLimit, value)) / valueLimit) * 40; const yTotal = (value: number) => 90 - (Math.max(0, value) / totalTop) * 80; const barWidth = Math.min(3.8, 22 / periods.length); const totalLine = periods.map((row, index) => `${xFor(index)},${yTotal(row.total_positions)}`).join(" "); return <div className="min-w-0"><div className="mb-3 flex flex-wrap gap-x-4 gap-y-1 text-[10px] text-slate-400"><span className="inline-flex items-center gap-1.5"><i className="h-2 w-2 rounded-sm bg-emerald-400" />Position increases</span><span className="inline-flex items-center gap-1.5"><i className="h-2 w-2 rounded-sm bg-rose-400" />Position decreases</span><span className="inline-flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-blue-400" />Total positions</span></div><div className="grid grid-cols-[3.6rem_minmax(0,1fr)_4.25rem] gap-3"><div><p className="mb-1 text-[9px] font-semibold uppercase tracking-[.12em] text-slate-500">Value change</p><div className="flex h-48 flex-col justify-between text-right text-[10px] font-semibold tabular-nums text-slate-500">{valueTicks.map((tick) => <span key={tick}>{formatAxisValue(tick)}</span>)}</div></div><div className="min-w-0"><div className="relative h-48 overflow-hidden"><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="absolute inset-0 h-full w-full overflow-hidden">{[10, 30, 50, 70, 90].map((y) => <line key={y} x1="0" x2="100" y1={y} y2={y} stroke="rgba(148,163,184,.16)" vectorEffect="non-scaling-stroke" />)}{periods.map((row, index) => { const x = xFor(index); const incY = yValue(row.position_increase_value); const decY = yValue(row.position_decrease_value); return <g key={row.period}><rect x={x - barWidth - 0.4} y={incY} width={barWidth} height={50 - incY} rx=".5" fill="#42d3a7" opacity=".78" /><rect x={x + 0.4} y={50} width={barWidth} height={decY - 50} rx=".5" fill="#fb7185" opacity=".78" /></g>; })}<line x1="0" x2="100" y1="50" y2="50" stroke="rgba(148,163,184,.28)" vectorEffect="non-scaling-stroke" /><polyline points={totalLine} fill="none" stroke="#60a5fa" strokeWidth="1.6" vectorEffect="non-scaling-stroke" /></svg>{periods.map((row, index) => <span key={`${row.period}-dot`} className="absolute h-2 w-2 rounded-full border border-blue-100 bg-blue-400 shadow-[0_0_8px_rgba(96,165,250,.75)]" style={{ left: `calc(${xFor(index)}% - 4px)`, top: `calc(${yTotal(row.total_positions)}% - 4px)` }} />)}</div><div className="mt-2 grid gap-1 text-[10px] text-slate-500" style={{ gridTemplateColumns: `repeat(${periods.length}, minmax(0, 1fr))` }}>{periods.map((row) => <span key={row.period} className="truncate text-center">{row.period}</span>)}</div></div><div><p className="mb-1 text-[9px] font-semibold uppercase tracking-[.12em] text-slate-500">Total positions</p><div className="flex h-48 flex-col justify-between text-left text-[10px] font-semibold tabular-nums text-slate-500"><span>{formatNumber(totalTop)}</span><span>{formatNumber(totalTop / 2)}</span><span>0</span></div></div></div></div>; }
function SectorMomentum({ rows }: { rows: ProfileSectorPeriod[] }) { const movements = sectorMovements(rows); return !movements.length ? <p className="py-8 text-sm text-slate-400">No comparable sector periods are available.</p> : <div className="space-y-2.5">{movements.slice(0, 8).map((item) => <div key={item.label} className="grid grid-cols-[minmax(0,1fr)_3.5rem] items-center gap-3 text-xs"><span className="truncate text-slate-300">{item.label}</span><span className={`text-right font-semibold tabular-nums ${item.value >= 0 ? "text-emerald-300" : "text-rose-300"}`}>{item.value >= 0 ? "+" : ""}{formatMoney(item.value)}</span></div>)}</div>; }
function SectorMovers({ rows }: { rows: ProfileSectorPeriod[] }) { const movements = sectorMovements(rows); return !movements.length ? <p className="py-8 text-sm text-slate-400">No comparable sector periods are available.</p> : <div className="space-y-2.5">{movements.slice(0, 6).map((item) => <div key={item.label}><div className="flex items-center justify-between gap-3 text-xs"><span className="truncate text-slate-300">{item.label}</span><span className={item.value >= 0 ? "font-semibold text-emerald-300" : "font-semibold text-rose-300"}>{item.value >= 0 ? "+" : ""}{formatMoney(item.value)}</span></div><div className="mt-1.5 h-1 overflow-hidden rounded bg-slate-800"><div className="h-full rounded" style={{ width: `${Math.max(5, item.share * 100)}%`, backgroundColor: item.value >= 0 ? "#42d3a7" : "#fb7185" }} /></div></div>)}</div>; }
function ActivityColumns({ series }: { series: Array<{ label: string; value: number }> }) { if (!series.length) return <p className="flex h-36 items-center justify-center text-sm text-slate-400">No time-series records are available.</p>; const max = Math.max(...series.map((point) => Math.abs(point.value)), 1); return <div><div className="flex h-36 items-end gap-2 border-b border-white/10 px-1">{series.map((point) => <div key={point.label} className="flex min-w-0 flex-1 items-end"><div title={`${point.label}: ${formatMoney(point.value)}`} className="w-full rounded-t-sm bg-emerald-400/70" style={{ height: `${Math.max(3, (Math.abs(point.value) / max) * 132)}px` }} /></div>)}</div><div className="mt-2 flex justify-between gap-3 text-[10px] text-slate-500"><span>{series[0].label}</span><span>{series[series.length - 1].label}</span></div></div>; }
function LegendRow({ label, color, value }: { label: string; color: string; value: string }) { return <div className="flex items-center justify-between gap-3 text-xs"><span className="flex items-center gap-2 text-slate-300"><i className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: color }} />{label}</span><span className="font-semibold tabular-nums text-white">{value}</span></div>; }
function OverviewGlow() { return <div aria-hidden className="pointer-events-none absolute inset-x-0 top-0 h-48 opacity-60 [background:radial-gradient(ellipse_at_70%_0%,rgba(52,211,153,.16),transparent_38%),radial-gradient(ellipse_at_25%_0%,rgba(59,130,246,.11),transparent_44%)]" />; }
function periodTotals(rows: ProfileSectorPeriod[]) { return rows.map((row) => ({ label: row.period, value: row.segments.reduce((sum, segment) => sum + (Number.isFinite(segment.value) ? segment.value : 0), 0) })); }
function metricValue(metrics: ProfileMetric[], label: string) { return metrics.find((metric) => metric.label === label)?.value ?? null; }
function sectorMovements(rows: ProfileSectorPeriod[]) { const latest = rows[rows.length - 1]; const previous = rows[rows.length - 2]; if (!latest || !previous) return []; const previousByLabel = new Map(previous.segments.map((segment) => [segment.label, segment.value])); const values = latest.segments.map((segment) => ({ label: segment.label, value: segment.value - (previousByLabel.get(segment.label) ?? 0) })); const max = Math.max(...values.map((item) => Math.abs(item.value)), 1); return values.sort((left, right) => Math.abs(right.value) - Math.abs(left.value)).map((item) => ({ ...item, share: Math.abs(item.value) / max })); }
function snapshotLabels(flavor: DashboardFlavor) { return flavor === "congress" ? ["Top member", "Most traded ticker", "Top buyer", "Most active sector"] : flavor === "insiders" ? ["Top net buyer", "Most traded ticker", "Recent purchases", "Cluster buying"] : ["Top institution", "Largest reported increase", "Most widely held stock", "Recent filing"]; }
function sectorLabels(rows: ProfileSectorPeriod[]) { const latest = rows[rows.length - 1]?.segments.map((segment) => segment.label) ?? []; return [...latest, ...Array.from(new Set(rows.flatMap((row) => row.segments.map((segment) => segment.label)))).filter((label) => !latest.includes(label))]; }
function orderedSegments(row: ProfileSectorPeriod, labels: string[]) { const byLabel = new Map(row.segments.map((segment) => [segment.label, segment])); return labels.map((label) => byLabel.get(label)).filter((segment): segment is NonNullable<typeof segment> => Boolean(segment)); }
function colorFor(label: string, labels: string[]) { return COLORS[Math.max(labels.indexOf(label), 0) % COLORS.length]; }
function overviewChartMetric(card: ProfilesSummaryResponse["cards"][number]) { const labelsByKind: Record<string, string[]> = { congress: ["trade"], insiders: ["trade"], institutions: ["portfolio"], departments: ["contract"] }; const preferred = labelsByKind[card.kind] ?? []; return card.metrics.find((metric) => preferred.some((label) => metric.label.toLowerCase().includes(label))) ?? card.metrics[0]; }
function overviewChartValues(metric: ProfileMetric | undefined, kind: string) { const current = Math.max(metric?.value ?? 0, 1); const changeFactor = typeof metric?.change_pct === "number" ? metric.change_pct / 100 : 0; const prior = typeof metric?.previous_value === "number" && Number.isFinite(metric.previous_value) ? Math.max(metric.previous_value, 0) : Math.max(current / Math.max(1 + changeFactor, 0.2), 1); const phase = kind.split("").reduce((sum, char) => sum + char.charCodeAt(0), 0) % 9; return Array.from({ length: 18 }, (_, index) => { const progress = index / 17; const wave = Math.sin((progress * Math.PI * 3.2) + phase) * 0.09 + Math.cos((progress * Math.PI * 5.1) + phase) * 0.04; const trend = prior + (current - prior) * progress; return Math.max(trend * (1 + wave), 0); }); }
function renderCell(row: Row, key: string, format?: CellFormat) { const value = row[key]; if (format === "link") { const href = typeof row.href === "string" ? row.href : typeof row.profile_href === "string" ? row.profile_href : typeof row.ticker_href === "string" ? row.ticker_href : null; const text = String(value ?? "-"); return href ? <Link href={href} prefetch={false} className="font-semibold text-emerald-200 hover:text-emerald-100">{text}</Link> : <span className="font-semibold text-emerald-200">{text}</span>; } if (format === "currency") return formatMoney(asNumber(value)); if (format === "number") return formatNumber(asNumber(value)); if (format === "percent") return typeof value === "number" ? `${value >= 0 ? "+" : ""}${value.toFixed(1)}%` : "-"; if (format === "date") return typeof value === "string" ? new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" }).format(new Date(value)) : "-"; return String(value ?? "-"); }
function formatMetric(metric?: ProfileMetric) { if (!metric) return "-"; return metric.format === "currency" ? formatMoney(metric.value) : formatNumber(metric.value); }
function formatUnknown(value: unknown) { return typeof value === "number" ? formatMoney(value) : "-"; }
function formatAxisValue(value: number) { return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", notation: "compact", maximumFractionDigits: 1 }).format(value); }
function formatCompactNumber(value: number) { return new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 }).format(value); }
function formatMoney(value?: number | null) { if (typeof value !== "number" || !Number.isFinite(value)) return "-"; return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", notation: "compact", maximumFractionDigits: 1 }).format(value); }
function formatDate(value: string) { const parsed = new Date(value); return Number.isNaN(parsed.valueOf()) ? value : new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", year: "numeric" }).format(parsed); }
function formatNumber(value?: number | null) { return typeof value === "number" && Number.isFinite(value) ? new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(value) : "-"; }
function roundAxisMax(value: number) { if (!Number.isFinite(value) || value <= 0) return 1; const magnitude = 10 ** Math.floor(Math.log10(value)); return Math.ceil(value / magnitude) * magnitude; }
function asNumber(value: unknown) { return typeof value === "number" && Number.isFinite(value) ? value : null; }
function stringAt(row: Row, keys: string[]) { for (const key of keys) if (typeof row[key] === "string" && row[key]) return row[key] as string; return null; }
function valueAt(row: Row, keys: string[]) { for (const key of keys) if (typeof row[key] === "number") return row[key]; return null; }
function profileIcon(kind: string) { return kind === "congress" ? "♜" : kind === "insiders" ? "♙" : kind === "institutions" ? "▦" : "◇"; }
function profileKind(type: string) { return type === "Congress" ? "congress" : type === "Insider" ? "insiders" : type === "Institution" ? "institutions" : "departments"; }
